 "Buyers add it for {amount}.": "Los compradores lo añaden por {amount}.",
 "Buyers are asked by email after they buy, on your schedule in Storelib Reviews.": "A los compradores se les pide por correo después de comprar, según tu calendario en Storelib Reviews.",
 "Buyers ask for a return from their order page, and you approve each one.": "Los compradores piden una devolución desde la página de su pedido y tú apruebas cada una.",
