 "Buyers can choose it": "Los compradores pueden elegirla",
 "Buyers can collect their order here for free instead of having it shipped.": "Los compradores pueden recoger aquí su pedido gratis en lugar de que se lo envíen.",
 "Buyers can no longer use it. Orders already placed with it keep their discount. To stop it for now instead, turn it off.": "Los compradores ya no podrán usarlo. Los pedidos ya hechos con él mantienen su descuento. Para pausarlo, desactívalo.",
