 "EN": "EN",
 "Each charge lands here with its invoice.": "Cada cargo aparece aquí con su factura.",
 "Each email goes to each person once, however often they trigger it. Someone who unsubscribes gets nothing more.": "Cada correo llega a cada persona una vez, por muchas veces que la active. Quien se da de baja no recibe nada más.",
 "Each item is priced by its own weight, then added up.": "Cada artículo se cobra por su peso y luego se suma.",
 "Each item pays the price of the step its weight reaches. Two 0.5 {unit} items at a 0 {unit2} step of $3 pay $6.": "Cada artículo paga el precio del tramo que alcanza su peso. Dos artículos de 0,5 {unit} en un tramo de 0 {unit2} de 3 $ pagan 6 $.",
 "Each link needs a label and an https:// address.": "Cada enlace necesita un texto y una dirección https://.",
 "Each new order for this location is sent here": "Cada pedido nuevo de esta ubicación se envía aquí",
 "Each new order is sent to your own system as a signed request. Set the address in Integrations.": "Cada pedido nuevo se envía a tu propio sistema como una solicitud firmada. Pon la dirección en Integraciones.",
 "Each new order with items from here is emailed to this partner with the items and the address. You add their tracking number in Orders when they ship.": "Cada pedido nuevo con artículos de aquí se envía por correo a este socio con los artículos y la dirección. Añades su número de seguimiento en Pedidos cuando envíen.",
 "Each order is printed and shipped for you.": "Cada pedido se imprime y se envía por ti.",
 "Each order starts it once. The same order never starts it twice.": "Cada pedido la inicia una vez. El mismo pedido nunca la inicia dos veces.",
 "Each question needs an answer.": "Cada pregunta necesita una respuesta.",
 "Each rule needs a title.": "Cada norma necesita un título.",
 "Each sale becomes available about {settleDays} days after it is paid. That wait is set by our payment partner for your country and protects against refunds and disputes.": "Cada venta está disponible unos {settleDays} días después de pagarse. Esa espera la fija nuestro socio de pagos para tu país y protege frente a reembolsos y disputas.",
 "Each sale becomes available after a short settlement wait set by our payment partner for your country.": "Cada venta está disponible tras una breve espera de liquidación que fija nuestro socio de pagos para tu país.",
 "Each variant has its own quantity, in Variants below.": "Cada variante tiene su propia cantidad, en Variantes abajo.",
 "Earlier": "Antes",
 "Earnings summary (CSV)": "Resumen de ingresos (CSV)",
