 "Members": "Miembros",
 "Members are told about announcements.": "Los miembros reciben aviso de los anuncios.",
 "Members can comment on posts here.": "Los miembros pueden comentar las publicaciones aquí.",
 "Members can read it; nobody can post. Bringing it back makes it a draft.": "Los miembros pueden leerla; nadie puede publicar. Recuperarla la convierte en borrador.",
 "Members can see who else is here.": "Los miembros pueden ver quién más está aquí.",
 "Members can still read it. Nobody can post or join until you bring it back. Nothing is deleted.": "Los miembros aún pueden leerla. Nadie puede publicar ni unirse hasta que la recuperes. No se borra nada.",
 "Members earn points when their posts and comments get reactions, and climb levels. A leaderboard shows in the community.": "Los miembros ganan puntos cuando sus publicaciones y comentarios reciben reacciones, y suben de nivel. Se muestra una clasificación en la comunidad.",
