 "Members pay for a tier to join.": "Los miembros pagan un nivel para unirse.",
 "Members pay monthly or yearly to join your community.": "Los miembros pagan mensual o anualmente para unirse a tu comunidad.",
 "Members pay once, in a checkout inside the community. ": "Los miembros pagan una vez, en un pago dentro de la comunidad. ",
 "Members pay once, in a checkout inside the community. The meeting link, the address and who else is going open when they have a ticket.": "Los miembros pagan una vez, en un pago dentro de la comunidad. El enlace de la reunión, la dirección y quién más va se muestran cuando tienen entrada.",
 "Members pay through Stripe. You can add a yearly price or more tiers later.": "Los miembros pagan con Stripe. Puedes añadir un precio anual o más niveles después.",
 "Members pay to join, every month, every year or once.": "Los miembros pagan por unirse, cada mes, cada año o una vez.",
 "Members pay you through Stripe. Nobody can join a paid community until payouts are connected.": "Los miembros te pagan con Stripe. Nadie puede unirse a una comunidad de pago hasta que conectes las transferencias.",
 "Members pay {amount} once, in a checkout inside the community. ": "Los miembros pagan {amount} una vez, en un pago dentro de la comunidad. ",
 "Members pay {priceText}.": "Los miembros pagan {priceText}.",
 "Members paying now, including anyone whose card is being retried. Somebody who cancelled keeps access until their period ends and is not counted.": "Miembros que pagan ahora, incluido quien tiene la tarjeta en reintento. Quien canceló mantiene el acceso hasta que termine su periodo y no se cuenta.",
 "Members post": "Publican los miembros",
 "Members reach levels by taking part. Below it, they see the program with the level it opens at.": "Los miembros alcanzan niveles participando. Por debajo, ven el programa con el nivel en que se abre.",
 "Members see it under Learn.": "Los miembros lo ven en Aprender.",
