 "There are no rules yet. Write them in Rules and policies.": "Aún no hay normas. Escríbelas en Normas y políticas.",
 "There are no subscribers to export": "No hay suscriptores para exportar",
 "There is no payment on that ticket to give back.": "Esa entrada no tiene ningún pago que devolver.",
