 "There is nothing available to cash out yet.": "Aún no hay nada disponible para retirar.",
 "There were no paying members at the start of this period, so there is no rate yet.": "No había miembros de pago al inicio de este periodo, así que aún no hay tasa.",
 "These photos are too large together. Send fewer, or smaller ones.": "Estas fotos pesan demasiado juntas. Envía menos o más pequeñas.",
 "These products have no weight saved: weigh the parcel.": "Estos productos no tienen peso guardado: pesa el paquete.",
 "These will appear on your OnePage": "Aparecerán en tu OnePage",
 "They are off for now. You can turn them on in": "Por ahora están desactivadas. Puedes activarlas en",
 "They are real starter projects rather than presets, and they come after the editor. Start blank or with AI for now.": "Son proyectos de inicio reales, no ajustes predefinidos, y llegarán después del editor. Por ahora empieza en blanco o con IA.",
 "They are removed from your files, and anything that still shows one of them will show nothing.": "Se quitan de tus archivos, y donde aún se muestre alguno no se verá nada.",
 "They are unsubscribed and get no more of your emails.": "Se da de baja y no recibe más correos tuyos.",
 "They can ask again later.": "Pueden volver a pedirlo más tarde.",
 "They can open the community and post again, and keep their points, level and posts.{free}": "Puede abrir la comunidad y publicar de nuevo, y conserva sus puntos, nivel y publicaciones.{free}",
 "They can read everything but cannot post, comment, react or chat until it ends.": "Puede leerlo todo, pero no publicar, comentar, reaccionar ni chatear hasta que termine.",
 "They can't place an order until they click the link we email them when they sign up. Turns on sign in as well.": "No pueden hacer un pedido hasta que pulsen el enlace que les enviamos al registrarse. También activa el inicio de sesión.",
 "They get access again now, and keep their points, level and posts.{free}": "Recupera el acceso ahora y conserva sus puntos, nivel y publicaciones.{free}",
 "They get in without paying, and they are told what the ticket would have cost.": "Entran sin pagar y se les dice cuánto habría costado la entrada.",
 "They get this tier without paying, until you end it.": "Obtiene este nivel sin pagar hasta que lo termines.",
 "They have {points} now. ": "Ahora tiene {points}. ",
